// ============================================================
// NEPSE NEWS INTELLIGENCE — EMAIL HTML BUILDER
// n8n Code Node
// ============================================================

// ------------------------------------------------------------
// 1. GET AI OUTPUT
// ------------------------------------------------------------

const data = $input.first().json;

// Depending on the Structured Output Parser configuration,
// the parsed object may be directly in `output`.
const report = data.output ?? data;


// ------------------------------------------------------------
// 2. HELPERS
// ------------------------------------------------------------

function escapeHtml(value) {
  if (value === null || value === undefined) return '';

  return String(value)
    .replace(/&/g, '&amp;')
    .replace(/</g, '&lt;')
    .replace(/>/g, '&gt;')
    .replace(/"/g, '&quot;')
    .replace(/'/g, '&#039;');
}


function formatDate(dateString) {
  if (!dateString) return '';

  const date = new Date(dateString);

  if (Number.isNaN(date.getTime())) {
    return escapeHtml(dateString);
  }

  return date.toLocaleDateString('en-GB', {
    day: '2-digit',
    month: 'short',
    year: 'numeric'
  });
}


function relevanceClass(relevance) {
  const value = String(relevance || '').toLowerCase();

  if (value === 'high') return 'high';
  if (value === 'medium') return 'medium';

  return 'low';
}


function renderTags(items) {

  if (!Array.isArray(items) || items.length === 0) {
    return '';
  }

  return `
    <div class="tags">
      ${items.map(item => `
        <span class="tag">${escapeHtml(item)}</span>
      `).join('')}
    </div>
  `;
}


function renderSources(sources) {

  if (!Array.isArray(sources) || sources.length === 0) {
    return '';
  }

  return `
    <div class="sources">

      ${sources.map(source => {

        const name = escapeHtml(source?.name || 'Source');
        const published = formatDate(source?.published);
        const url = source?.url || '';

        return `
          <div class="source-row">

            <div>
              <strong>${name}</strong>

              ${published
                ? `<span class="published"> · ${published}</span>`
                : ''
              }
            </div>

            ${
              url
                ? `<a href="${escapeHtml(url)}"
                     target="_blank"
                     rel="noopener noreferrer">
                     Read source
                   </a>`
                : ''
            }

          </div>
        `;

      }).join('')}

    </div>
  `;
}


function renderNewsCard(article) {

  const relevance = article?.relevance || 'Low';

  return `
    <article class="news-card">

      <div class="card-top">

        <span class="relevance ${relevanceClass(relevance)}">
          ${escapeHtml(relevance)}
        </span>

      </div>

      <h3>
        ${escapeHtml(article?.title || 'Untitled Event')}
      </h3>

      <div class="field">

        <div class="field-title">
          WHAT HAPPENED
        </div>

        <p>
          ${escapeHtml(article?.whatHappened || '')}
        </p>

      </div>

      <div class="field">

        <div class="field-title">
          COMPANIES / SECTORS
        </div>

        ${renderTags(article?.companiesSectors)}

      </div>

      <div class="field why">

        <div class="field-title">
          WHY IT MATTERS
        </div>

        <p>
          ${escapeHtml(article?.whyItMatters || '')}
        </p>

      </div>

      ${renderSources(article?.sources)}

    </article>
  `;
}


function renderSection(title, icon, subtitle, articles) {

  if (!Array.isArray(articles) || articles.length === 0) {
    return '';
  }

  return `
    <section class="section">

      <div class="section-heading">

        <div class="section-icon">
          ${icon}
        </div>

        <div>

          <h2>
            ${escapeHtml(title)}
          </h2>

          <p>
            ${escapeHtml(subtitle)}
          </p>

        </div>

      </div>

      <div class="news-grid">

        ${articles.map(renderNewsCard).join('')}

      </div>

    </section>
  `;
}


// ------------------------------------------------------------
// 3. DATA
// ------------------------------------------------------------

const company =
  report.company ||
  'NEPSE';

const generatedSummary =
  report.generatedSummary ||
  'No executive summary was provided.';

const directNews =
  Array.isArray(report.directCompanyNews)
    ? report.directCompanyNews
    : [];

const sectorNews =
  Array.isArray(report.sectorNews)
    ? report.sectorNews
    : [];

const marketNews =
  Array.isArray(report.marketNews)
    ? report.marketNews
    : [];

const overallMarketView =
  Array.isArray(report.overallMarketView)
    ? report.overallMarketView
    : [];

const bottomLine =
  report.bottomLine ||
  'No additional conclusion was provided.';

const disclaimer =
  report.disclaimer ||
  'This is a news summary, not financial advice or a recommendation to buy, sell, or hold any security.';


// ------------------------------------------------------------
// 4. CURRENT DATE
// ------------------------------------------------------------

const generatedDate = new Date().toLocaleDateString('en-GB', {
  day: '2-digit',
  month: 'short',
  year: 'numeric'
});


// ------------------------------------------------------------
// 5. OVERALL MARKET VIEW
// ------------------------------------------------------------

const marketViewHtml =
  overallMarketView.length > 0

    ? overallMarketView
        .map(point => `
          <li>${escapeHtml(point)}</li>
        `)
        .join('')

    : `
      <li>
        No significant overall market observations were identified.
      </li>
    `;


// ------------------------------------------------------------
// 6. COMPLETE HTML EMAIL
// ------------------------------------------------------------

const html = `

<!DOCTYPE html>

<html lang="en">

<head>

<meta charset="UTF-8">

<meta name="viewport"
      content="width=device-width, initial-scale=1.0">

<title>
  ${escapeHtml(company)} — NEPSE News Intelligence
</title>

<style>

* {
  box-sizing: border-box;
}

body {

  margin: 0;

  background: #f4f6f8;

  color: #17202a;

  font-family:
    -apple-system,
    BlinkMacSystemFont,
    "Segoe UI",
    Roboto,
    Helvetica,
    Arial,
    sans-serif;

  line-height: 1.6;
}

.container {

  width: min(
    1100px,
    calc(100% - 32px)
  );

  margin: 0 auto;
}


/* HERO */

.hero {

  background:
    linear-gradient(
      135deg,
      #101820,
      #1d2b36
    );

  color: white;

  padding: 48px 0;
}

.hero-inner {

  display: flex;

  justify-content: space-between;

  align-items: flex-end;

  gap: 30px;
}

.eyebrow {

  font-size: 13px;

  font-weight: 700;

  letter-spacing: 1.5px;

  opacity: .7;

  text-transform: uppercase;
}

.hero h1 {

  margin: 8px 0 4px;

  font-size: 42px;

  line-height: 1.1;
}

.hero-subtitle {

  margin: 0;

  color: #cbd5dc;

  font-size: 17px;
}

.date {

  color: #cbd5dc;

  font-size: 14px;

  white-space: nowrap;
}


/* SUMMARY */

.summary {

  margin: 28px 0;

  padding: 24px 26px;

  background: white;

  border-radius: 14px;

  border: 1px solid #e3e7eb;

  box-shadow:
    0 5px 20px rgba(0,0,0,.04);
}

.summary-label {

  font-size: 12px;

  font-weight: 800;

  letter-spacing: 1.2px;

  color: #697681;

  margin-bottom: 8px;
}

.summary p {

  margin: 0;

  font-size: 17px;
}


/* SECTIONS */

.section {

  margin: 42px 0;
}

.section-heading {

  display: flex;

  align-items: center;

  gap: 14px;

  margin-bottom: 18px;
}

.section-icon {

  width: 42px;

  height: 42px;

  display: flex;

  align-items: center;

  justify-content: center;

  background: white;

  border-radius: 11px;

  border: 1px solid #e3e7eb;

  font-size: 20px;
}

.section-heading h2 {

  margin: 0;

  font-size: 23px;
}

.section-heading p {

  margin: 2px 0 0;

  color: #71808b;

  font-size: 14px;
}


/* CARDS */

.news-grid {

  display: grid;

  grid-template-columns:
    repeat(2, minmax(0, 1fr));

  gap: 18px;
}

.news-card {

  background: white;

  border: 1px solid #e2e7eb;

  border-radius: 14px;

  padding: 24px;

  box-shadow:
    0 4px 16px rgba(0,0,0,.035);
}

.card-top {

  margin-bottom: 12px;
}

.relevance {

  display: inline-block;

  padding: 4px 9px;

  border-radius: 999px;

  font-size: 10px;

  font-weight: 800;

  letter-spacing: .7px;
}

.relevance.high {

  background: #e6f7ed;

  color: #147a43;
}

.relevance.medium {

  background: #fff5dc;

  color: #936400;
}

.relevance.low {

  background: #edf1f4;

  color: #687681;
}

.news-card h3 {

  margin: 0 0 20px;

  font-size: 20px;

  line-height: 1.35;
}

.field {

  margin-top: 17px;
}

.field-title {

  font-size: 10px;

  font-weight: 800;

  letter-spacing: 1px;

  color: #84919a;
}

.field p {

  margin: 4px 0 0;

  font-size: 14px;

  color: #394750;
}

.why {

  padding-top: 15px;

  border-top:
    1px solid #edf0f2;
}

.tags {

  display: flex;

  flex-wrap: wrap;

  gap: 6px;

  margin-top: 8px;
}

.tag {

  background: #f0f3f5;

  color: #53616b;

  padding: 3px 8px;

  border-radius: 6px;

  font-size: 11px;
}


/* SOURCES */

.sources {

  margin-top: 20px;

  padding-top: 14px;

  border-top:
    1px solid #edf0f2;
}

.source-row {

  display: flex;

  justify-content: space-between;

  align-items: center;

  gap: 10px;

  font-size: 12px;
}

.source-row + .source-row {

  margin-top: 7px;
}

.source-row strong {

  color: #37444d;
}

.published {

  color: #87939c;
}

.source-row a {

  color: #1769aa;

  text-decoration: none;

  font-weight: 700;

  white-space: nowrap;
}

.source-row a:hover {

  text-decoration: underline;
}


/* OVERALL VIEW */

.insight-box {

  background: #101820;

  color: white;

  border-radius: 16px;

  padding: 28px;

  margin: 42px 0;
}

.insight-box h2 {

  margin-top: 0;

  font-size: 22px;
}

.insight-box ul {

  margin: 0;

  padding-left: 20px;
}

.insight-box li {

  margin: 9px 0;

  color: #dce4e9;
}


/* BOTTOM LINE */

.bottom-line {

  background: white;

  border: 1px solid #e2e7eb;

  border-radius: 14px;

  padding: 26px;

  margin: 25px 0 40px;
}

.bottom-line h2 {

  margin-top: 0;

  font-size: 21px;
}

.bottom-line p {

  margin-bottom: 0;

  font-size: 16px;
}


/* DISCLAIMER */

.disclaimer {

  border-top:
    1px solid #dce1e5;

  padding:
    20px 0 40px;

  color: #7b8790;

  font-size: 12px;
}


/* MOBILE */

@media (max-width: 750px) {

  .hero {

    padding: 34px 0;
  }

  .hero-inner {

    display: block;
  }

  .hero h1 {

    font-size: 32px;
  }

  .date {

    margin-top: 12px;
  }

  .news-grid {

    grid-template-columns: 1fr;
  }

  .summary {

    padding: 20px;
  }

  .news-card {

    padding: 20px;
  }

  .source-row {

    align-items: flex-start;

    flex-direction: column;

    gap: 4px;
  }

}

</style>

</head>


<body>


<!-- ========================================================
     HERO
========================================================= -->

<header class="hero">

  <div class="container hero-inner">

    <div>

      <div class="eyebrow">
        NEPSE News Intelligence
      </div>

      <h1>
        ${escapeHtml(company)}
      </h1>

      <p class="hero-subtitle">
        Company-focused Nepal financial-market intelligence
      </p>

    </div>

    <div class="date">

      Generated ${generatedDate}

    </div>

  </div>

</header>


<main class="container">


<!-- ========================================================
     EXECUTIVE SUMMARY
========================================================= -->

<div class="summary">

  <div class="summary-label">
    EXECUTIVE SUMMARY
  </div>

  <p>
    ${escapeHtml(generatedSummary)}
  </p>

</div>


<!-- ========================================================
     DIRECT COMPANY NEWS
========================================================= -->

${renderSection(
  'Direct Company News',
  '🏢',
  'Developments specifically involving the requested company',
  directNews
)}


<!-- ========================================================
     SECTOR NEWS
========================================================= -->

${renderSection(
  'Sector News',
  '🏦',
  'Developments affecting the company through its sector',
  sectorNews
)}


<!-- ========================================================
     BROADER MARKET NEWS
========================================================= -->

${renderSection(
  'Broader Market News',
  '📊',
  'Relevant developments across Nepal’s financial market',
  marketNews
)}


<!-- ========================================================
     OVERALL MARKET VIEW
========================================================= -->

<section class="insight-box">

  <h2>
    Overall Market View
  </h2>

  <ul>

    ${marketViewHtml}

  </ul>

</section>


<!-- ========================================================
     BOTTOM LINE
========================================================= -->

<section class="bottom-line">

  <h2>
    Bottom Line
  </h2>

  <p>
    ${escapeHtml(bottomLine)}
  </p>

</section>


<!-- ========================================================
     DISCLAIMER
========================================================= -->

<div class="disclaimer">

  ⚠️ ${escapeHtml(disclaimer)}

</div>


</main>

</body>

</html>
`;


// ------------------------------------------------------------
// 7. RETURN HTML FOR NEXT NODE
// ------------------------------------------------------------

return [

  {
    json: {

      company,

      subject:
        `${company} — NEPSE News Intelligence`,

      html

    }
  }

];
